CREATE TABLE IF NOT EXISTS payroll_employees (id INTEGER PRIMARY KEY AUTOINCREMENT, employee_number TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, id_number TEXT, job_title TEXT NOT NULL, age_band TEXT NOT NULL DEFAULT 'UNDER_65', base_salary REAL NOT NULL DEFAULT 0, meat_benefit REAL NOT NULL DEFAULT 0, benefit_balance REAL NOT NULL DEFAULT 0, housing_deduction REAL NOT NULL DEFAULT 0, pension_deduction REAL NOT NULL DEFAULT 0, medical_deduction REAL NOT NULL DEFAULT 0, other_taxable_benefits REAL NOT NULL DEFAULT 0, other_deductions REAL NOT NULL DEFAULT 0, account_number TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payroll_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, payroll_number TEXT NOT NULL UNIQUE, employee_id INTEGER NOT NULL, pay_period TEXT NOT NULL, base_salary REAL NOT NULL, meat_benefit REAL NOT NULL, opening_benefit_balance REAL NOT NULL, meat_purchases REAL NOT NULL, meat_excess_deduction REAL NOT NULL, closing_benefit_balance REAL NOT NULL, overtime_hours REAL NOT NULL, overtime_rate REAL NOT NULL, overtime_pay REAL NOT NULL, other_taxable_benefits REAL NOT NULL, gross_remuneration REAL NOT NULL, taxable_remuneration REAL NOT NULL, paye REAL NOT NULL, housing_deduction REAL NOT NULL, pension_deduction REAL NOT NULL, medical_deduction REAL NOT NULL, other_deductions REAL NOT NULL, total_deductions REAL NOT NULL, net_pay REAL NOT NULL, tax_year TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(employee_id) REFERENCES payroll_employees(id));
CREATE INDEX IF NOT EXISTS idx_payroll_runs_period_employee ON payroll_runs(pay_period,employee_id);
